DROP DATABASE IF EXISTS `boat_sales`;
CREATE DATABASE `boat_sales` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `boat_sales`;

CREATE TABLE `customers` (
  `customer_id` INT PRIMARY KEY NOT NULL,
  `first_name` VARCHAR(50),
  `last_name` VARCHAR(50),
  `gender` VARCHAR(50),
  `age` DECIMAL(18,2),
  `email` VARCHAR(50),
  `phone` VARCHAR(50),
  `city` VARCHAR(50),
  `state` VARCHAR(50),
  `postal_code` DECIMAL(18,2),
  `signup_date` VARCHAR(50),
  UNIQUE KEY `uk_customers_email` (`email`) 
) ENGINE=InnoDB;

CREATE TABLE `products` (
  `product_id` INT PRIMARY KEY NOT NULL,
  `brand` VARCHAR(50),
  `product_name` VARCHAR(200),
  `price` DECIMAL(18,2),
  `category` VARCHAR(50),
  `sub_category` VARCHAR(50),
  `color` VARCHAR(50),
  `model_number` VARCHAR(50)
) ENGINE=InnoDB;

CREATE TABLE `orders` (
  `order_id` INT PRIMARY KEY NOT NULL,
  `customer_id` INT,
  `order_date` DATE,
  `shipped_date` DATE,
  `delivery_date` DATE,
  `payment_method` VARCHAR(50),
  `shipping_address` TEXT,
  `order_status` VARCHAR(50),
 CONSTRAINT `fk_orders_customer` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`)
) ENGINE=InnoDB;

CREATE TABLE `order_details` (
  `order_id` INT,
  `product_id` INT,
  `order_detail_id` DECIMAL(18,2),
  `quantity` INT,
  `discount_percent` DECIMAL(18,2),
  `unit_price` DECIMAL(18,2),
  `total_price` DECIMAL(18,2),
CONSTRAINT `fk_od_order` FOREIGN KEY (`order_id`) REFERENCES `orders`(`order_id`),
CONSTRAINT `fk_od_product` FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB;

CREATE TABLE `returns` (
  `return_id` INT PRIMARY KEY NOT NULL,
  `order_detail_id` INT,
  `return_date` DATE,
  `reason` VARCHAR(50),
  `refund_status` VARCHAR(50)
) ENGINE=InnoDB;






